package com.ngocdevv.nativecook.blocks.animations.superchargecard

// Lossless bundled bytes keep this copyable block independent of the app resource registry.
internal object SuperchargeBoldData {
    fun bytes(): ByteArray =
        java.util.zip
            .GZIPInputStream(
                java.io.ByteArrayInputStream(
                    android.util.Base64.decode(chunks.joinToString(""), android.util.Base64.DEFAULT)
                )
            )
            .use { it.readBytes() }

    private val chunks =
        arrayOf(
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
        )
}
